content:
/* Performance Pack only: two equal families, four square image choices in one row. */
body[data-heading-palette144="ultimate-pack"] .performance-flavours163{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;gap:20px;width:100%;margin:0 0 28px}
body[data-heading-palette144="ultimate-pack"] .performance-flavours163>fieldset{min-width:0;width:100%;margin:0;padding:0}
body[data-heading-palette144="ultimate-pack"] .performance-flavours163 .shared-image-options119>div{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px!important;align-items:start}
body[data-heading-palette144="ultimate-pack"] .performance-flavours163 .shared-image-options119 button{width:100%;min-width:0;flex-basis:auto;overflow-wrap:anywhere}
body[data-heading-palette144="ultimate-pack"] .performance-flavours163 .shared-image-options119 button img{width:min(76px,100%);height:auto;aspect-ratio:1;object-fit:contain}
@media(max-width:767px){
 body[data-heading-palette144="ultimate-pack"] .performance-flavours163{gap:14px}
 body[data-heading-palette144="ultimate-pack"] .performance-flavours163 .shared-image-options119 button{font-size:11px}
 body[data-heading-palette144="ultimate-pack"] .performance-flavours163 .shared-image-options119 button img{width:min(64px,100%)}
}
